class SnapshotArray {
    vector<vector<pair<int, int>>> data;
    int snap_count;
public:
    SnapshotArray(int length) {
        data.resize(length);
        snap_count = 0;
    }

    void set(int index, int val) {
        if (!data[index].empty() && data[index].back().first == snap_count) {
            data[index].back().second = val;
        } else {
            data[index].push_back({snap_count, val});
        }
    }

    int snap() {
        return snap_count++;
    }

    int get(int index, int snap_id) {
        auto& vec = data[index];
        auto it = upper_bound(vec.begin(), vec.end(), snap_id,
            [](int s, const pair<int,int>& p) { return s < p.first; });
        if (it == vec.begin()) return 0;
        --it;
        return it->second;
    }
};
